import random
from itertools import combinations

def check_girth(edges, n):
    """Check if graph has girth >= 5 (no 3-cycles or 4-cycles)"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check for triangles (3-cycles)
    for u in range(n):
        neighbors = list(adj[u])
        for i in range(len(neighbors)):
            for j in range(i+1, len(neighbors)):
                v, w = neighbors[i], neighbors[j]
                if w in adj[v]:
                    return False  # Triangle found

    # Check for 4-cycles
    for u in range(n):
        neighbors = list(adj[u])
        for i in range(len(neighbors)):
            for j in range(i+1, len(neighbors)):
                v, w = neighbors[i], neighbors[j]
                # Check if v and w share a common neighbor other than u
                common = adj[v] & adj[w] - {u}
                if common:
                    return False  # 4-cycle found

    return True

def check_coloring(edges, n, max_colors):
    """Check if graph is colorable with max_colors using greedy/backtracking"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    color = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(max_colors):
            valid = True
            for neighbor in adj[v]:
                if color[neighbor] == c:
                    valid = False
                    break
            if valid:
                color[v] = c
                if backtrack(v + 1):
                    return True
                color[v] = -1
        return False

    return backtrack(0)

def try_random_graph(n, num_edges, max_colors, max_attempts=10000):
    """Try to find a random graph satisfying constraints"""
    for attempt in range(max_attempts):
        edges = random.sample(list(combinations(range(n), 2)), num_edges)
        if check_girth(edges, n):
            if check_coloring(edges, n, max_colors):
                return edges
    return None

