def verify_graph(edges, n, max_colors):
    """Comprehensive verification of the graph"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        assert 0 <= u < v < n, f"Invalid edge ({u}, {v})"
        adj[u].add(v)
        adj[v].add(u)

    # Check for triangles
    for u in range(n):
        neighbors = list(adj[u])
        for i in range(len(neighbors)):
            for j in range(i+1, len(neighbors)):
                v, w = neighbors[i], neighbors[j]
                if w in adj[v]:
                    return False, f"Triangle: {u}-{v}-{w}"

    # Check for 4-cycles
    for u in range(n):
        neighbors = list(adj[u])
        for i in range(len(neighbors)):
            for j in range(i+1, len(neighbors)):
                v, w = neighbors[i], neighbors[j]
                common = adj[v] & adj[w] - {u}
                if common:
                    return False, f"4-cycle involving {u}, {v}, {w}, {common}"

    # Check coloring
    color = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        for c in range(max_colors):
            valid = all(color[neighbor] != c for neighbor in adj[v])
            if valid:
                color[v] = c
                if backtrack(v + 1):
                    return True
                color[v] = -1
        return False

    if not backtrack(0):
        return False, "Not colorable"

    return True, f"Valid! Coloring: {color}, Edges: {len(edges)}"

